package com.xavier.backend.customers.model;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import jakarta.persistence.Version;
import java.time.Instant;
import java.util.UUID;
import org.hibernate.annotations.UuidGenerator;

/**
 * A customer ("Cliente", spec §5; D72): identity, fiscal id and contact notes, company-wide (P38). Never deleted:
 * documents and the ledger refer to it, so it is deactivated instead. {@code name_search}, the folded name the
 * trigram index serves, is generated by the database and not mapped.
 */
@Entity
@Table(schema = "customers", name = "customer")
public class Customer {

    @Id
    @UuidGenerator(style = UuidGenerator.Style.VERSION_7)
    private UUID id;

    @Column(nullable = false, length = 160)
    private String name;

    @Column(length = 30)
    private String taxId;

    @Column(length = 254)
    private String email;

    private String notes;

    @Column(nullable = false)
    private boolean active;

    @Column(nullable = false, updatable = false)
    private Instant createdAt;

    @Column(nullable = false)
    private Instant updatedAt;

    @Version
    private Long version;

    protected Customer() {
        // JPA
    }

    public static Customer create(String name, String taxId, String email, String notes, Instant now) {
        Customer customer = new Customer();
        customer.createdAt = now;
        customer.update(name, taxId, email, notes, true, now);
        return customer;
    }

    public void update(String name, String taxId, String email, String notes, boolean active, Instant now) {
        this.name = Text.required(name, "name");
        this.taxId = Text.optional(taxId);
        this.email = Text.optional(email);
        this.notes = Text.optional(notes);
        this.active = active;
        this.updatedAt = now;
    }

    public UUID getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public String getTaxId() {
        return taxId;
    }

    public String getEmail() {
        return email;
    }

    public String getNotes() {
        return notes;
    }

    public boolean isActive() {
        return active;
    }

    public long getVersion() {
        return version == null ? 0 : version;
    }
}
